const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
export function denseProjectileArbitrationPresentation(input, reducedMotion = false, reducedFlash = false) { const crowd = clamp01(Math.max(0, input.projectileCount - 4) / 16), age = clamp01(Math.max(0, input.indexFromNewest) / 14), lane = clamp01(input.laneProximity), stress = clamp01(crowd * .5 + age * .3 + lane * .3), relief = input.critical ? .4 : 1; return { stress, bodyAlphaScale: 1, trailAlphaScale: Math.max(input.critical ? .78 : .38, 1 - stress * .58 * relief) * (reducedMotion ? .92 : 1) * (reducedFlash ? .94 : 1), presentationOnly: true }; }
export function denseImpactArbitrationPresentation(input, reducedFlash = false) { const crowd = clamp01(Math.max(0, input.impactCount - 3) / 14), age = clamp01(Math.max(0, input.indexFromNewest) / 12), hero = clamp01(input.heroProximity), stress = clamp01(crowd * .5 + age * .34 + hero * .28), relief = input.critical ? .46 : 1, flash = reducedFlash ? .9 : 1, fillAlphaScale = Math.max(input.critical ? .56 : .18, 1 - stress * .68 * relief) * flash, edgeAlphaScale = Math.max(fillAlphaScale, .64 + (1 - stress) * .24); return { stress, canonicalAlphaScale: 1, fillAlphaScale, edgeAlphaScale, presentationOnly: true }; }
export function denseHazardArbitrationPresentation(input, reducedFlash = false) { const crowd = clamp01(Math.max(0, input.hazardCount - 2) / 9), age = clamp01(Math.max(0, input.indexFromNewest) / 8), lane = clamp01(input.laneProximity), stress = clamp01(crowd * .46 + age * .3 + lane * .3), flash = reducedFlash ? .9 : 1; return { stress, edgeAlphaScale: input.telegraph || input.critical ? Math.max(.92, .98 * (reducedFlash ? .98 : 1)) : Math.max(.68, 1 - stress * .24), fillAlphaScale: Math.max(input.critical ? .58 : .24, 1 - stress * .56) * flash, presentationOnly: true }; }
export function denseSafeLaneArbitrationPresentation(input, reducedFlash = false) { const load = clamp01((Math.max(0, input.hazardCount) + Math.max(0, input.projectileCount)) / 24), confidence = clamp01(input.confidence), focus = clamp01(load + (input.critical ? .22 : 0)); return { pathAlphaFloor: Math.max(input.critical ? .94 : .92, .92 + confidence * .06), safeLaneAlphaScale: 1 + focus * (.08 + .04 * confidence) * (reducedFlash ? .76 : 1), secondaryAlphaScale: Math.max(.52, 1 - focus * .4) * (reducedFlash ? .92 : 1), presentationOnly: true }; }
export function denseSilhouetteArbitrationPresentation(input, reducedMotion = false) { const crowd = clamp01(Math.max(0, input.silhouetteCount - 2) / 8), age = clamp01(Math.max(0, input.indexFromNewest) / 8), stress = clamp01(crowd * .58 + age * .34), action = input.owner === 'special' ? 1 : input.owner === 'attack' ? .9 : input.owner === 'hit' ? .7 : input.owner === 'recovery' ? .48 : .18; return { stress, bodyAlphaScale: 1, directionAlphaScale: Math.max(input.critical ? .78 : .66, .72 + action * .22 - stress * .1), trailAlphaScale: Math.max(.42, 1 - stress * .48) * (reducedMotion ? .88 : 1), secondaryAlphaScale: Math.max(.5, 1 - stress * .44), presentationOnly: true }; }
export function denseBattlefieldArbitrationPresentation(input, reducedMotion = false, reducedFlash = false) { const critical = clamp01(Math.max(0, input.criticalCount) / 3), load = clamp01((Math.max(0, input.hazardCount) * 1.4 + Math.max(0, input.projectileCount) + Math.max(0, input.impactCount) + Math.max(0, input.silhouetteCount)) / 36), stress = clamp01(load * .88 + critical * .16); return { stress, criticalAlphaScale: 1, canonicalBodyAlphaScale: 1, bossTelegraphEdgeAlphaScale: 1, safeLaneAlphaScale: input.safeLaneVisible ? 1 + stress * .1 * (reducedFlash ? .76 : 1) : 1, secondaryAlphaScale: Math.max(.54, 1 - stress * .42) * (reducedMotion ? .92 : 1) * (reducedFlash ? .92 : 1), presentationOnly: true }; }
